{
  "findings": [
    {
      "check_id": "CKV_AZURE_112",
      "title": "Key Vault key is not HSM-backed",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The key uses the software-backed RSA key type, so private key operations are not protected by a hardware security module."
    },
    {
      "check_id": "CKV_AZURE_40",
      "title": "Key Vault key has no expiration date",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "No expiration_date is configured, allowing the key to remain valid indefinitely and increasing the risk associated with stale or compromised key material."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_key\" \"generated\" {\n  name            = \"terragoat-generated-certificate-${var.environment}\"\n  key_vault_id    = azurerm_key_vault.example.id\n  key_type        = \"RSA-HSM\"\n  key_size        = 2048\n  expiration_date = \"2027-12-31T23:59:59Z\"\n  key_opts = [\n    \"decrypt\",\n    \"encrypt\",\n    \"sign\",\n    \"unwrapKey\",\n    \"verify\",\n    \"wrapKey\",\n  ]\n}\n",
  "fix_summary": "Changed the key type to RSA-HSM so the key is hardware-backed and added a future expiration date to prevent indefinite validity."
}
